add_filter( 'posts_search', 'perfectpixel_search_by_sku', 20, 2 );

function perfectpixel_search_by_sku( $search, $query ) {
	global $wpdb;
	if ( is_admin() || ! $query->is_main_query() || ! $query->is_search() || '' === $search ) {
		return $search;
	}
	$term = trim( (string) $query->get( 's' ) );
	if ( mb_strlen( $term ) < 2 ) {
		return $search;
	}
	$ids = $wpdb->get_col(
		$wpdb->prepare(
			"SELECT DISTINCT IF( p.post_parent > 0, p.post_parent, p.ID ) FROM {$wpdb->prefix}wc_product_meta_lookup l
			INNER JOIN {$wpdb->posts} p ON p.ID = l.product_id
			WHERE l.sku LIKE %s LIMIT 200",
			'%' . $wpdb->esc_like( $term ) . '%'
		)
	);
	$ids = array_filter( array_map( 'intval', $ids ) );
	if ( ! $ids || 0 !== strpos( ltrim( $search ), 'AND' ) ) {
		return $search;
	}
	// Turn " AND (title/content match)" into " AND ((title/content match) OR ID IN (sku matches))".
	return ' AND ( ' . substr( ltrim( $search ), 3 ) . " OR {$wpdb->posts}.ID IN (" . implode( ',', $ids ) . ') ) ';
}
